#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
#include <climits>
using namespace std;

using vi = vector<int>;
using vvi = vector<vi>;
using pii = pair<int,int>;

const int INF = 1e9;

struct Edge {
    int to, rev, cap;
};

class FlowGraph {
public:
    int N;
    vector<vector<Edge>> adj;
    vi level, ptr;

    FlowGraph(int n) : N(n), adj(n), level(n), ptr(n) {}

    void addEdge(int u, int v, int cap) {
        adj[u].push_back({v, (int)adj[v].size(), cap});
        adj[v].push_back({u, (int)adj[u].size()-1, 0});
    }

    bool bfs(int s, int t) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        q.push(s);
        level[s] = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto& e : adj[u]) {
                if (level[e.to] == -1 && e.cap > 0) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] != -1;
    }

    int dfs(int u, int t, int flow) {
        if (u == t) return flow;
        for (int& i = ptr[u]; i < (int)adj[u].size(); ++i) {
            auto& e = adj[u][i];
            if (level[e.to] == level[u] + 1 && e.cap > 0) {
                int pushed = dfs(e.to, t, min(flow, e.cap));
                if (pushed > 0) {
                    e.cap -= pushed;
                    adj[e.to][e.rev].cap += pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    int maxFlow(int s, int t) {
        int total = 0;
        while (bfs(s, t)) {
            fill(ptr.begin(), ptr.end(), 0);
            while (int pushed = dfs(s, t, INF)) {
                total += pushed;
            }
        }
        return total;
    }
};

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n, t;
    cin >> n >> t;
    vector<string> field(n), capsule(n);
    int src = 2 * n * n, dst = src + 1;
    FlowGraph g(2 * n * n + 2);

    int zx = -1, zy = -1;
    for (int i = 0; i < n; ++i) {
        cin >> field[i];
        for (int j = 0; j < n; ++j) {
            if (field[i][j] == 'Z') {
                zx = i; zy = j;
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        cin >> capsule[i];
        for (int j = 0; j < n; ++j) {
            if (isdigit(capsule[i][j])) {
                g.addEdge(i * n + j + n * n, dst, capsule[i][j] - '0');
            }
        }
    }

    vector<vector<int>> distZ(n, vector<int>(n, INF));
    queue<pii> q;
    distZ[zx][zy] = 0;
    q.push({zx, zy});
    int dx[] = {-1, 1, 0, 0}, dy[] = {0, 0, -1, 1};

    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        if (distZ[x][y] == t) continue;
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n && capsule[nx][ny] != 'Y' && distZ[nx][ny] == INF) {
                distZ[nx][ny] = distZ[x][y] + 1;
                if (isdigit(capsule[nx][ny])) {
                    g.addEdge(zx * n + zy, nx * n + ny + n * n, INF);
                }
                q.push({nx, ny});
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(field[i][j])) {
                g.addEdge(src, i * n + j, field[i][j] - '0');
                vector<vector<int>> distS(n, vector<int>(n, INF));
                queue<pii> q2;
                distS[i][j] = 0;
                q2.push({i, j});
                while (!q2.empty()) {
                    auto [x, y] = q2.front(); q2.pop();
                    if (distS[x][y] == t) continue;
                    for (int d = 0; d < 4; ++d) {
                        int nx = x + dx[d], ny = y + dy[d];
                        if (nx >= 0 && nx < n && ny >= 0 && ny < n && capsule[nx][ny] != 'Y' && distS[nx][ny] == INF) {
                            distS[nx][ny] = distS[x][y] + 1;
                            if (isdigit(capsule[nx][ny])) {
                                g.addEdge(i * n + j, nx * n + ny + n * n, INF);
                            }
                            q2.push({nx, ny});
                        }
                    }
                }
            }
        }
    }

    cout << g.maxFlow(src, dst) << '\n';
    return 0;
}
